const W = dev().w, H = dev().h;
let seed = 91; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const mk = (w, h) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };
const names = [];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const rr = (g, x, y, w, h, r) => { g.beginPath(); g.roundRect(x, y, w, h, r); };
const GOLD = (g, x0, y0, x1, y1) => { const q = g.createLinearGradient(x0, y0, x1, y1); q.addColorStop(0, '#fff2b0'); q.addColorStop(0.3, '#e8b73c'); q.addColorStop(0.55, '#a8761a'); q.addColorStop(0.8, '#f1c95a'); q.addColorStop(1, '#8a5c10'); return q; };
const CHROME = (g, x0, y0, x1, y1) => { const q = g.createLinearGradient(x0, y0, x1, y1); q.addColorStop(0, '#fbfcff'); q.addColorStop(0.25, '#aeb4c0'); q.addColorStop(0.5, '#f2f4f8'); q.addColorStop(0.75, '#7b808c'); q.addColorStop(1, '#d4d8e0'); return q; };
const RW = 62, RH = 150, PITCH = 92, RY = 70, REELX = [55, 117, 211, 273];
const ball = (g, x, y, r, c0, c1, c2) => { const q = g.createRadialGradient(x - r * 0.35, y - r * 0.4, r * 0.1, x, y, r); q.addColorStop(0, c0); q.addColorStop(0.6, c1); q.addColorStop(1, c2); g.beginPath(); g.arc(x, y, r, 0, 7); g.fillStyle = q; g.fill(); };
const shine = (g, x, y, r) => { g.beginPath(); g.ellipse(x - r * 0.35, y - r * 0.45, r * 0.28, r * 0.16, -0.6, 0, 7); g.fillStyle = 'rgba(255,255,255,0.78)'; g.fill(); };
const leaf = (g, x, y, len, ang) => { g.save(); g.translate(x, y); g.rotate(ang); g.beginPath(); g.moveTo(0, 0); g.quadraticCurveTo(len * 0.45, -len * 0.3, len, 0); g.quadraticCurveTo(len * 0.45, len * 0.3, 0, 0); const q = g.createLinearGradient(0, -len * 0.25, 0, len * 0.25); q.addColorStop(0, '#7ed04a'); q.addColorStop(1, '#2b7a1c'); g.fillStyle = q; g.fill(); g.strokeStyle = 'rgba(15,60,10,0.55)'; g.lineWidth = 0.7; g.stroke(); g.beginPath(); g.moveTo(0, 0); g.lineTo(len * 0.95, 0); g.strokeStyle = 'rgba(225,255,190,0.65)'; g.stroke(); g.restore(); };
const fill = (g, c0, c1, c2, x0, y0, x1, y1) => { const q = g.createLinearGradient(x0, y0, x1, y1); q.addColorStop(0, c0); q.addColorStop(0.55, c1); q.addColorStop(1, c2); g.fillStyle = q; };
// fruits 0-9, drawn inside about +-26 px of (cx, cy)
function fruit(g, id, cx, cy, s) {
  g.save(); g.translate(cx, cy); g.scale(s, s); g.shadowColor = 'rgba(0,0,0,0.35)'; g.shadowBlur = 4; g.shadowOffsetY = 2;
  if (id === 0) { g.strokeStyle = '#4c7f2a'; g.lineWidth = 2.2; g.lineCap = 'round'; g.beginPath(); g.moveTo(-10, 0); g.quadraticCurveTo(-6, -18, 2, -26); g.moveTo(11, 2); g.quadraticCurveTo(10, -16, 2, -26); g.stroke(); leaf(g, 2, -25, 17, -0.5); ball(g, -10, 11, 12, '#ff7a86', '#d5112b', '#650010'); shine(g, -10, 11, 12); ball(g, 11, 13, 12, '#ff7a86', '#d5112b', '#650010'); shine(g, 11, 13, 12); }
  else if (id === 1) { g.beginPath(); g.moveTo(-27, 3); g.bezierCurveTo(-22, -14, -8, -20, 6, -19); g.bezierCurveTo(18, -18, 25, -10, 28, -4); g.bezierCurveTo(24, 12, 12, 20, -4, 19); g.bezierCurveTo(-16, 18, -24, 12, -27, 3); const q = g.createRadialGradient(-6, -8, 2, 0, 0, 30); q.addColorStop(0, '#fff68a'); q.addColorStop(0.6, '#f2d200'); q.addColorStop(1, '#b88a00'); g.fillStyle = q; g.fill(); g.shadowColor = 'transparent'; for (let i = 0; i < 26; i++) { g.fillStyle = 'rgba(160,120,0,0.28)'; g.beginPath(); g.arc(-18 + rnd() * 42, -12 + rnd() * 26, 0.7, 0, 7); g.fill(); } g.beginPath(); g.ellipse(-27, 3, 3.4, 2.4, 0.4, 0, 7); g.fillStyle = '#d6b000'; g.fill(); g.beginPath(); g.ellipse(28, -4, 3, 2.2, 0.5, 0, 7); g.fill(); shine(g, -2, -4, 16); leaf(g, 6, -19, 14, -0.9); }
  else if (id === 2) { ball(g, 0, 2, 23, '#ffd070', '#ff8e12', '#a84400'); g.shadowColor = 'transparent'; for (let i = 0; i < 40; i++) { const a = rnd() * 6.28, r = Math.sqrt(rnd()) * 21; g.fillStyle = 'rgba(150,60,0,0.22)'; g.beginPath(); g.arc(Math.cos(a) * r, 2 + Math.sin(a) * r, 0.8, 0, 7); g.fill(); } shine(g, 0, 2, 23); g.beginPath(); g.arc(0, -20, 3.2, 0, 7); g.fillStyle = '#4c8a22'; g.fill(); leaf(g, 1, -21, 16, -0.4); }
  else if (id === 3) { g.beginPath(); g.arc(0, -8, 27, 0, Math.PI); g.closePath(); fill(g, '#5fbf4a', '#2b8a2a', '#145a1a', 0, -8, 0, 20); g.fill(); g.shadowColor = 'transparent'; g.beginPath(); g.arc(0, -8, 23.5, 0, Math.PI); g.closePath(); g.fillStyle = '#f3f8d8'; g.fill(); g.beginPath(); g.arc(0, -8, 21, 0, Math.PI); g.closePath(); fill(g, '#ff7a80', '#e6213a', '#a30f26', 0, -8, 0, 14); g.fill(); g.strokeStyle = 'rgba(20,90,20,0.5)'; g.lineWidth = 1; for (let i = -2; i <= 2; i++) { g.beginPath(); g.moveTo(i * 8, 18); g.lineTo(i * 10, 18 - 7); g.stroke(); } for (const [x, y] of [[-12, 0], [-4, 4], [5, 0], [13, 3], [-8, 10], [2, 11], [10, 9]]) { g.save(); g.translate(x, y); g.rotate(0.3); g.beginPath(); g.ellipse(0, 0, 1.6, 2.8, 0, 0, 7); g.fillStyle = '#16100a'; g.fill(); g.restore(); } g.fillStyle = 'rgba(255,255,255,0.4)'; g.fillRect(-26, -9, 52, 2); }
  else if (id === 4) { g.strokeStyle = '#5a7a30'; g.lineWidth = 2.4; g.beginPath(); g.moveTo(0, -12); g.quadraticCurveTo(2, -22, 8, -26); g.stroke(); leaf(g, 2, -22, 16, -2.4); for (const [x, y] of [[-14, -8], [0, -10], [14, -8], [-8, 3], [6, 3], [-17, 5], [18, 5], [0, 14], [-9, 16], [9, 16], [0, 24]]) { ball(g, x, y, 8.6, '#c79af0', '#7a35b8', '#30104f'); shine(g, x, y, 8.6); } }
  else if (id === 5) { g.beginPath(); g.moveTo(0, 24); g.bezierCurveTo(-28, 8, -24, -14, -7, -15); g.bezierCurveTo(-2, -17, 2, -17, 7, -15); g.bezierCurveTo(24, -14, 28, 8, 0, 24); const q = g.createRadialGradient(-6, -6, 2, 0, 2, 30); q.addColorStop(0, '#ff7a7a'); q.addColorStop(0.6, '#e0182c'); q.addColorStop(1, '#8a0a18'); g.fillStyle = q; g.fill(); g.shadowColor = 'transparent'; for (let r = 0; r < 5; r++) for (let c = 0; c < 4 - (r === 4 ? 2 : 0); c++) { const x = (c - 1.5 + (r % 2) * 0.5) * 9 * (1 - Math.abs(r - 1) * 0.0), y = -8 + r * 6.4; if (Math.abs(x) < 20 - r * 3.2) { g.beginPath(); g.ellipse(x, y, 1.1, 1.8, 0, 0, 7); g.fillStyle = '#f7e27a'; g.fill(); } } shine(g, -4, -4, 20); for (let i = 0; i < 5; i++) leaf(g, 0, -15, 12, -Math.PI / 2 + (i - 2) * 0.55); }
  else if (id === 6) { g.beginPath(); g.moveTo(0, -14); g.bezierCurveTo(-10, -23, -27, -14, -25, 5); g.bezierCurveTo(-23, 21, -8, 27, 0, 21); g.bezierCurveTo(8, 27, 23, 21, 25, 5); g.bezierCurveTo(27, -14, 10, -23, 0, -14); const q = g.createRadialGradient(-8, -6, 2, 0, 4, 30); q.addColorStop(0, '#ff8a70'); q.addColorStop(0.55, '#d9141e'); q.addColorStop(1, '#7a0610'); g.fillStyle = q; g.fill(); g.shadowColor = 'transparent'; g.beginPath(); g.ellipse(14, 12, 6, 10, 0.5, 0, 7); g.fillStyle = 'rgba(200,220,60,0.28)'; g.fill(); shine(g, -8, -2, 18); g.strokeStyle = '#5a3a1a'; g.lineWidth = 2.4; g.beginPath(); g.moveTo(0, -14); g.quadraticCurveTo(1, -20, 5, -25); g.stroke(); leaf(g, 2, -19, 16, -0.5); }
  else if (id === 7) { g.beginPath(); g.moveTo(0, -24); g.bezierCurveTo(8, -24, 10, -10, 14, -2); g.bezierCurveTo(28, 10, 18, 27, 0, 27); g.bezierCurveTo(-18, 27, -28, 10, -14, -2); g.bezierCurveTo(-10, -10, -8, -24, 0, -24); const q = g.createRadialGradient(-6, 6, 2, 0, 6, 32); q.addColorStop(0, '#f4ee8a'); q.addColorStop(0.6, '#a8c82a'); q.addColorStop(1, '#4e7a10'); g.fillStyle = q; g.fill(); g.shadowColor = 'transparent'; for (let i = 0; i < 24; i++) { g.fillStyle = 'rgba(90,70,10,0.3)'; g.beginPath(); g.arc(-14 + rnd() * 28, -4 + rnd() * 28, 0.7, 0, 7); g.fill(); } shine(g, -6, 6, 20); g.strokeStyle = '#5a3a1a'; g.lineWidth = 2.4; g.beginPath(); g.moveTo(0, -24); g.quadraticCurveTo(2, -28, 6, -31); g.stroke(); leaf(g, 2, -22, 15, -0.6); }
  else if (id === 8) { ball(g, 0, 3, 22, '#b88ad8', '#6a2a8a', '#260a38'); g.shadowColor = 'transparent'; g.beginPath(); g.arc(0, 3, 22, 0.1, 1.2); g.strokeStyle = 'rgba(30,5,45,0.55)'; g.lineWidth = 1.6; g.stroke(); g.beginPath(); g.ellipse(-6, -4, 12, 7, -0.6, 0, 7); g.fillStyle = 'rgba(220,200,240,0.22)'; g.fill(); shine(g, 0, 3, 22); g.strokeStyle = '#5a3a1a'; g.lineWidth = 2.2; g.beginPath(); g.moveTo(0, -18); g.quadraticCurveTo(1, -24, 5, -27); g.stroke(); leaf(g, 2, -21, 15, -0.5); }
  else { g.beginPath(); g.moveTo(-26, -16); g.bezierCurveTo(-30, 8, -4, 30, 26, 10); g.lineTo(28, 3); g.bezierCurveTo(8, 18, -12, 8, -11, -20); g.closePath(); const q = g.createLinearGradient(-20, -16, 20, 20); q.addColorStop(0, '#fff08a'); q.addColorStop(0.5, '#f1c80a'); q.addColorStop(1, '#a87a00'); g.fillStyle = q; g.fill(); g.shadowColor = 'transparent'; g.strokeStyle = 'rgba(120,80,0,0.4)'; g.lineWidth = 0.9; g.beginPath(); g.moveTo(-20, -14); g.bezierCurveTo(-22, 8, -2, 22, 24, 8); g.stroke(); g.beginPath(); g.arc(-19, -19, 4, 0, 7); g.fillStyle = '#4a2f10'; g.fill(); g.beginPath(); g.arc(27, 6, 3, 0, 7); g.fill(); }
  g.restore();
}
// one reel tile (a face of the cylinder): paper, a fruit above, the digit below
function tile(d) {
  const t = mk(RW, PITCH), g = t.getContext('2d'); g.fillStyle = '#fffdf6'; g.fillRect(0, 0, RW, PITCH);
  fruit(g, d, RW / 2, 25, 0.88);
  g.font = '66px "Anton"'; g.textAlign = 'center'; g.textBaseline = 'alphabetic'; g.lineJoin = 'round';
  g.save(); g.shadowColor = 'rgba(0,0,0,0.3)'; g.shadowBlur = 2; g.shadowOffsetY = 1.5; g.lineWidth = 4; g.strokeStyle = '#2a0a12'; g.strokeText(String(d), RW / 2, 89); const q = g.createLinearGradient(0, 40, 0, 89); q.addColorStop(0, '#ff3a48'); q.addColorStop(1, '#b3081c'); g.fillStyle = q; g.fillText(String(d), RW / 2, 89); g.restore();
  g.fillStyle = 'rgba(0,0,0,0.12)'; g.fillRect(0, 0, RW, 1.2);
  return t;
}
function reel(tiles, d, off) {
  const c = mk(RW, RH), g = c.getContext('2d'); g.fillStyle = '#fffdf6'; g.fillRect(0, 0, RW, RH);
  for (let k = -2; k <= 2; k++) g.drawImage(tiles[((d + k) % 10 + 10) % 10], 0, (RH - PITCH) / 2 + k * PITCH + off);
  let q = g.createLinearGradient(0, 0, 0, RH); q.addColorStop(0, 'rgba(10,20,50,0.72)'); q.addColorStop(0.15, 'rgba(10,20,50,0.26)'); q.addColorStop(0.34, 'rgba(10,20,50,0)'); q.addColorStop(0.66, 'rgba(10,20,50,0)'); q.addColorStop(0.85, 'rgba(10,20,50,0.26)'); q.addColorStop(1, 'rgba(10,20,50,0.72)'); g.fillStyle = q; g.fillRect(0, 0, RW, RH);
  q = g.createLinearGradient(0, 0, RW, 0); q.addColorStop(0, 'rgba(10,20,50,0.4)'); q.addColorStop(0.12, 'rgba(10,20,50,0)'); q.addColorStop(0.88, 'rgba(10,20,50,0)'); q.addColorStop(1, 'rgba(10,20,50,0.4)'); g.fillStyle = q; g.fillRect(0, 0, RW, RH);
  return c;
}

